  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Oritavancin, a large glycopeptide antibiotic, achieved only 5% CSF/plasma penetration in a rabbit meningitis model, directly demonstrating poor CNS access for a high-molecular-weight glycosylated antibiotic; this high-transfer evidence supports a fail prediction for the similarly glycosylated polycyclic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Mithramycin, a glycosylated aromatic natural product, showed a peak CSF:plasma ratio of 0.12 in monkeys with little brain distribution, providing direct primate evidence of inadequate CNS access; supports fail.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Erythromycin, a large macrolide antibiotic, produced CSF concentrations of only 0.1-2.5 µg/ml versus serum 8-12 µg/ml in humans with meningitis, confirming poor BBB penetration for a large polar antibiotic; supports fail.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Loganin, an iridoid glycoside, had the lowest brain levels among tissues in rats, indicating difficulty crossing the BBB; supports fail for glycoside-bearing molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Digitoxin, a cardiac glycoside, exhibited a very low CSF/plasma ratio of 0.01-0.03 in dogs, showing that glycosylated polycyclic natural products do not readily cross the BBB; supports fail.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a large, heavily hydroxylated tetracycline-like glycoside with a polar sugar and trifluoroacetamide substituent. Multiple high-transfer experimental records from glycosylated/polycyclic antibiotics and natural products consistently show poor CSF/brain penetration after systemic dosing. No credible evidence supports meaningful CNS access; therefore predict fail.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for the exact query molecule.",
    "No data on transporter-mediated efflux or active uptake for the query.",
    "Tetracycline-class exceptions such as minocycline are not represented in the retrieved evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

